import "./setupPolyFills.js";
export { AssetInformation, UserAssetInfo } from './decoders.js';
export { FirstStageSDK } from './client.js';
import algosdk from 'algosdk';

export type UserTxnWithSigner = {
  txn: algosdk.Transaction;
  signer?: algosdk.TransactionSigner;
};

export type ProcessedSwapTransaction = {
  txn: algosdk.Transaction
  needsUserSignature: boolean
  deflexSignature?: FirstStageDeflexTransactionSignature
  originalGroupId?: Uint8Array
}

export class FirstStageDeflexTransaction {
  public data: string;
  public group: string;
  public logicSigBlob: Uint8Array | boolean;
  public signature: FirstStageDeflexTransactionSignature | boolean;

  constructor(
    data: string,
    group: string,
    logicSigBlob: Uint8Array | boolean,
    signature: FirstStageDeflexTransactionSignature | boolean
  ) {
    this.data = data;
    this.group = group;
    this.logicSigBlob = logicSigBlob;
    this.signature = signature;
  }

  static fromApiResponse(apiResponse: {
    data: string;
    group: string;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    logicSigBlob: any | false;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    signature:
      | { type: 'logic_signature' | 'secret_key'; value: any }
      | false;
  }): FirstStageDeflexTransaction {
    return new FirstStageDeflexTransaction(
      apiResponse.data,
      apiResponse.group,
      apiResponse.logicSigBlob !== false
        ? Uint8Array.from(Object.values(apiResponse.logicSigBlob))
        : false,
      apiResponse.signature !== false
        ? FirstStageDeflexTransactionSignature.fromApiResponse(apiResponse.signature)
        : false
    );
  }
}

export type FirstStageSwapTxnsResponse = {
  txns: {
    data: string
    group: string
    logicSigBlob: any | false
    signature:
      | {
          type: 'logic_signature' | 'secret_key'
          value: any
        }
      | false
  }[]
}

export class FirstStageDeflexTransactionSignature {
  public type: 'logic_signature' | 'secret_key'
  public value: Uint8Array
  constructor(type: 'logic_signature' | 'secret_key', value: Uint8Array) {
    this.type = type
    this.value = value
  }
  static fromApiResponse(apiResponse: { type: 'logic_signature' | 'secret_key'; value: any }) {
    return new FirstStageDeflexTransactionSignature(apiResponse.type, Uint8Array.from(Object.values(apiResponse.value)))
  }
}